pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address oracleAddr) public {
        // Admissible domain: any non-zero contract address (exclude zero and EOAs to pass initialization)
        vm.assume(oracleAddr != address(0));
        // Create a minimal contract at the fuzzed address to satisfy isContract check during initialization
        vm.etch(oracleAddr, hex"00");

        // Initialize c with a valid oracle address
        C.ProductInfo memory info;
        info.oracle = IOracleProvider(oracleAddr);
        info.payoffDefinition = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType.PASS_THROUGH,
            payoffDirection: PayoffDefinitionLib.PayoffDirection.NEUTRAL,
            data: bytes30(0)
        });
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(type(uint256).max);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: Fixed18.wrap(0),
            maxRate: Fixed18.wrap(0),
            targetRate: Fixed18.wrap(0),
            targetUtilization: UFixed18.wrap(0)
        });
        info.name = "test";
        info.symbol = "TEST";

        vm.prank(address(this));
        c.initialize(info);

        // Assert: c.oracle() must return the original non-zero oracle address (reference behavior)
        // Buggy mutant returns address(0) instead
        assertTrue(address(c.oracle()) == oracleAddr);
    }
}

