pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 oracleVersion) public {
        vm.assume(oracleVersion > 1 && oracleVersion < type(uint256).max);
        // We need to ensure the oracle has been synced at least once so there is a latest version > 0.
        // Since we cannot rely on internal sync through external calls without a full environment,
        // we verify that when the oracle returns data for a specific version, currentVersion()
        // matches that version's data, not version 0.
        // The property: currentVersion() should not be calling atVersion(0) internally.
        // Instead, it should be calling oracle().currentVersion().
        // We can check that the version returned by currentVersion() is not hardcoded to 0.

        // Deploy a mock oracle that implements IOracleProvider
        MockOracle oracle = new MockOracle();
        // We need to initialize C with this oracle, but initialize() can only be called once.
        // Since setUp already deploys C, we use a fresh deployment with the mock oracle.
        // To test the property, we can deploy a new C and call currentVersion() before any sync.
        // However, currentVersion() is a view function that reads from the oracle.
        // The bug is that it calls atVersion(0) instead of currentVersion().
        // We can detect this by checking if the returned version is 0 while the oracle's current version is not 0.

        // Let's set the mock oracle to have current version = 5
        oracle.setCurrentVersion(5, uint256(block.timestamp), int256(1e18));
        oracle.setVersion(0, 0, int256(0)); // version 0 data is different

        // Now we need a C that has the oracle set. We can do this by deploying a new C
        // and using a trick: we can call initialize through a controller-like pattern.
        // But since initialize requires a controller that is a contract, we'll simplify.
        // The test must work with the deployed c from setUp.
        // However, c is already initialized with whatever oracle it has.
        // The key insight: the mutant always returns atVersion(0) data.
        // So if the correct implementation would return version != 0, the mutant returns version == 0.
        // We can test this by ensuring the oracle's current version is not 0.

        // For the already-deployed c, we can't change its oracle.
        // But we can test the property directly if we can make the oracle return non-zero current version.
        // The deployed c in setUp uses whatever oracle was in its constructor (it's just new C()).
        // Since C has no constructor, the oracle is not set until initialize is called.
        // So calling currentVersion() on uninitialized C will likely revert or return default data.
        // To properly test, we need to initialize C with a mock oracle that we control.

        // Better approach: Deploy a helper that is the controller and initializes C.
        // But that's complex. Instead, we can observe that the mutant always returns version 0 data.
        // If we can make the real oracle's currentVersion() return version > 0,
        // then the correct c.currentVersion() will have version > 0,
        // while the mutant's will have version == 0.
        // We can check this by calling c.currentVersion() and checking its version field.

        // Since we cannot easily initialize C with a custom oracle in this test setup,
        // we'll deploy a fresh C and use a minimal controller to initialize it.
        // Let's create a MockController that can initialize C.

        // Actually, we can simply use the fact that the mutant hardcodes atVersion(0),
        // so it will always return the data for version 0 regardless of the oracle's actual current version.
        // If we can set the oracle's current version to something > 0 after initialization,
        // but the mutant will still query version 0.
        // However, the oracle is an external dependency. We can mock it using a contract.

        // Let's use a known approach: deploy a fresh C, deploy a MockOracle and MockController,
        // initialize C, then advance the oracle's version, and check currentVersion().
        // The correct one should return the advanced version, the mutant returns version 0.

        MockOracle mockOracle = new MockOracle();
        MockController mockController = new MockController(address(mockOracle));

        // Deploy fresh C
        C freshC = new C();

        // Set up product info
        IProduct.ProductInfo memory info;
        info.name = "Test";
        info.symbol = "T";
        info.oracle = IOracleProvider(address(mockOracle));
        info.payoffDefinition = PayoffDefinition({payoffType: PayoffDefinitionLib.PayoffType(0), payoffDirection: PayoffDefinitionLib.PayoffDirection(0), data: bytes30(0)});
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });

        // Initialize through the mock controller
        vm.prank(address(mockController));
        freshC.initialize(info);

        // Set initial oracle version to 1 (non-zero)
        mockOracle.setCurrentVersion(1, uint256(block.timestamp), int256(1e18));
        mockOracle.setVersion(1, uint256(block.timestamp), int256(1e18));
        mockOracle.setVersion(0, 0, int256(0)); // version 0 is different (price 0)

        // Now, the correct currentVersion() should return version 1 with price 1e18 (after transform)
        // The mutant currentVersion() returns atVersion(0) which has price 0 (after transform)

        IOracleProvider.OracleVersion memory result = freshC.currentVersion();

        // General rule: currentVersion() must return the same data as calling atVersion(the actual latest version).
        // Here, latest version is 1 (since we set it). So currentVersion().price should equal atVersion(1).price
        IOracleProvider.OracleVersion memory expected = freshC.atVersion(1);

        // Assert that the version from currentVersion() matches the actual oracle's current version (1)
        assert(result.version == 1);
        // Additional check: the price should match atVersion(1)
        // But the transform is applied, so both should be the same if the transform is deterministic.
        assert(result.price.unwrap() == expected.price.unwrap());
    }
}

contract MockOracle is IOracleProvider {
    OracleVersion public currentVersionData;
    mapping(uint256 => OracleVersion) public versions;

    function setCurrentVersion(uint256 _version, uint256 _timestamp, int256 _price) external {
        currentVersionData = OracleVersion(_version, _timestamp, Fixed18.wrap(_price));
        versions[_version] = currentVersionData;
    }

    function setVersion(uint256 _version, uint256 _timestamp, int256 _price) external {
        versions[_version] = OracleVersion(_version, _timestamp, Fixed18.wrap(_price));
    }

    function sync() external returns (OracleVersion memory) {
        return currentVersionData;
    }

    function currentVersion() external view returns (OracleVersion memory) {
        return currentVersionData;
    }

    function atVersion(uint256 oracleVersion) external view returns (OracleVersion memory) {
        return versions[oracleVersion];
    }
}

