// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 version) public {
        vm.assume(version > 0);
        vm.roll(version);
        try c.currentVersion() returns (IOracleProvider.OracleVersion memory latest) {
            try c.atVersion(c.latestVersion()) returns (IOracleProvider.OracleVersion memory atLatest) {
                assertTrue(
                    latest.version == atLatest.version &&
                    latest.timestamp == atLatest.timestamp &&
                    latest.price.eq(atLatest.price),
                    "currentVersion should match atVersion(latestVersion)"
                );
            } catch {
                assertTrue(false, "atVersion(latestVersion) reverted");
            }
        } catch {
            assertTrue(false, "currentVersion reverted");
        }
    }
}

