pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(address actor, uint256 amount) public {
        // Ensure we have a real account to prank
        vm.assume(actor != address(0));

        // The product must be settled (latestVersion > 0) to observe the difference.
        // Because C is complex and requires initialization plus a coordinator/oracle,
        // we drive the difference through the public pure/view path directly.
        // The mutant replaces oracle().currentVersion() with oracle().atVersion(0),
        // so c.currentVersion().version will be the stale oracle version 0.
        // The correct contract's currentVersion().version is the oracle's current version.
        // Oracle.currentVersion() is called by C; we mock it using a minimal helper.

        // Deploy a minimal oracle that returns different versions for currentVersion and atVersion(0).
        OracleMock oracle = new OracleMock();
        oracle.setVersion(42);

        // The target contract C must be initialized; we call initialize as the controller
        vm.prank(address(this));
        c.initialize(C.ProductInfo({
            name: "Test",
            symbol: "TST",
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType.PASS,
